for (Triangulation::All_faces_iterator face_it = triangulation.all_faces_begin(); face_it != triangulation.all_faces_end(); ++face_it) {
    face_it->info().processed = false;
    face_it->info().interior = false;
}

std::queue<Triangulation::Face_handle> face_queue;
bool found_exterior = false;

// Find an exterior face (unconstrained face on the convex hull)
for (Triangulation::All_faces_iterator face_it = triangulation.all_faces_begin(); face_it != triangulation.all_faces_end(); ++face_it) {
    bool has_unconstrained_edge = false;
    for (int i = 0; i < 3; ++i) {
        if (!triangulation.is_constrained(Edge(face_it, i))) {
            // Check if this edge is on the convex hull (neighbor is infinite)
            if (triangulation.is_infinite(face_it->neighbor(i))) {
                has_unconstrained_edge = true;
                break;
            }
        }
    }
    if (has_unconstrained_edge) {
        face_it->info().interior = false;
        face_it->info().processed = true;
        face_queue.push(face_it);
        found_exterior = true;
    }
}

if (!found_exterior) {
    // If no exterior face found, start with first face as interior (degenerate case)
    Triangulation::Face_handle first_face = triangulation.all_faces_begin();
    first_face->info().interior = true;
    first_face->info().processed = true;
    face_queue.push(first_face);
}

while (!face_queue.empty()) {
    Triangulation::Face_handle current_face = face_queue.front();
    face_queue.pop();

    for (int i = 0; i < 3; ++i) {
        Triangulation::Face_handle neighbor = current_face->neighbor(i);
        if (triangulation.is_infinite(neighbor)) continue;
        if (neighbor->info().processed) continue;

        // If the edge is constrained, it's a boundary and we don't propagate across it
        if (triangulation.is_constrained(Edge(current_face, i))) {
            neighbor->info().interior = !current_face->info().interior;
        } else {
            // Unconstrained edge: propagate same label (interior to interior, exterior to exterior)
            neighbor->info().interior = current_face->info().interior;
        }

        neighbor->info().processed = true;
        face_queue.push(neighbor);
    }
}

